#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    const char *USAGE = "USAGE";
    const char *TOO_LONG = "TOO_LONG";
    const char *ANAGRAM = "ANAGRAM";
    const char *NOT_ANAGRAM = "NOT_ANAGRAM";

    if (argc < 3) {
        puts(USAGE);
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= 1025 || strlen(s2) >= 1025) {
        puts(TOO_LONG);
        return 0;
    }

    int cnt1[256] = {0};
    int cnt2[256] = {0};

    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;               // ignore spaces
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A'); // case‑insensitive for letters
        cnt1[c]++;
    }
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;               // ignore spaces
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A');
        cnt2[c]++;
    }

    int is_anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            is_anagram = 0;
            break;
        }
    }

    puts(is_anagram ? ANAGRAM : NOT_ANAGRAM);
    return 0;
}
